// it. LLM_ATTN_GATHER=0 is the control arm — the block kernel P13 shipped.
func (g *AttnGPU) gather() bool {
	if v := os.Getenv("LLM_ATTN_GATHER"); v != "" {
		return v == "1"
	}
	return g.sparse && g.rows >= gathMinRows
}

